const $=selector=>document.querySelector(selector);
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const deviceTheme=window.matchMedia('(prefers-color-scheme: dark)');
let chosenTheme=null;
function setTheme(theme,persist=true){
 if(!['light','dark'].includes(theme))return;
 document.documentElement.dataset.theme=theme;
 document.querySelectorAll('[data-theme-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.themeChoice===theme)));
 if(persist){chosenTheme=theme;try{localStorage.setItem('sheprd-theme',theme)}catch{}}
}
function initializeTheme(){
 try{
  const saved=localStorage.getItem('sheprd-theme');
  if(['light','dark'].includes(saved))chosenTheme=saved;
  else{
   const legacy=localStorage.getItem('sheprd-mock-direction');
   if(legacy==='b'||legacy==='c'){chosenTheme=legacy==='b'?'light':'dark';localStorage.setItem('sheprd-theme',chosenTheme)}
  }
 }catch{}
 setTheme(chosenTheme||(deviceTheme.matches?'dark':'light'),false);
}
deviceTheme.addEventListener('change',event=>{if(chosenTheme===null)setTheme(event.matches?'dark':'light',false)});




const paths={chevron:'m9 5 7 7-7 7',branch:'M6 7v10M18 8a8 8 0 0 1-8 8H6',board:'M4 4h16v16H4zM9 4v12M15 4v8',arrow:'M5 12h14m-5-5 5 5-5 5',check:'m5 12 4 4L19 6',plus:'M12 5v14M5 12h14',message:'M4 4h16v12H9l-5 4z',folder:'M3 6h7l2 2h9v12H3z',send:'m6 11 6-6 6 6M12 5v14'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true">${name==='branch'?'<circle cx="6" cy="5" r="2"/><circle cx="6" cy="19" r="2"/><circle cx="18" cy="6" r="2"/>':''}<path d="${paths[name]||paths.arrow}"/></svg>`;
const chevron=open=>`<svg viewBox="0 0 16 16" aria-hidden="true"><path d="${open?'m4 6 4 4 4-4':'m6 4 4 4-4 4'}"/></svg>`;
const agent=(id,name,initial,role,tool='Codex')=>({id,name,initial,role,tool});
const H=window.sheprdData,{repositories,workspaces,projects,requests,permissionItems,deliveryItems,machineItems,subscriptionItems,projectMachines,futureProjectMachines,repositoryLocations,runtimeStates,workspacePreferences,threads,channels,alerts,taskStories,settings:sampleSettings}=H;
const heavySample=H.source==='heavy',firstProject=projects[0],thisMachine=machineItems.find(m=>m.role==='Master')||machineItems[0];

let state={repoId:firstProject?.repoId,projectId:firstProject?.id,view:'home',teamId:null,agentId:firstProject?.lead.id,tab:'chat',sprintId:null,taskId:null};
const drafts=new Map(),chatPositions=new Map(),positions=new Map(),teamTabs=new Map(),pending=new Map(),selectedWorkspaces=new Map();
const expandedRepos=new Set([firstProject?.repoId]),expandedProjects=new Set([firstProject?.id]),expandedTeams=new Set(firstProject?.teams[0]?[firstProject.id+'/'+firstProject.teams[0].id]:[]);
const p=()=>projects.find(x=>x.id===state.projectId),repo=()=>repositories.find(x=>x.id===state.repoId),team=()=>p()?.teams.find(x=>x.id===state.teamId);
const agents=project=>[project.lead,...project.teams.flatMap(x=>x.agents)],findAgent=(id,project=p())=>agents(project).find(x=>x.id===id);
const recipient=()=>state.agentId?findAgent(state.agentId):{id:state.teamId,name:team()?.name,role:'Team',tool:''};
const conversationKey=()=>`${state.projectId}/${state.agentId?'agent/'+state.agentId:'team/'+state.teamId}`;
const viewKey=()=>`${state.projectId}/${state.view}/${state.teamId}/${state.agentId}/${state.tab}/${state.sprintId}/${state.taskId}`;
// Board and Mocks keep the project lead's conversation beside them.
const leadBeside=()=>['board','mocks'].includes(state.view);
const isChat=()=>leadBeside()||state.view==='chat'&&state.tab==='chat';
const conversationScroller=()=>leadBeside()?$('#lead-chat-body'):$('#view-body');
const compactLead=matchMedia('(max-width:1100px)');
let leadPanelOpen=!compactLead.matches;
const projectRequests=(project=p())=>requests.filter(r=>r.projectId===project.id&&r.status==='open'&&r.holder!=='lead');
const projectWorkspace=(project=p())=>workspaces.find(w=>w.id===project.workspace);
const projectBranch=(project=p())=>`<span class="project-assigned-branch" title="Project branch: ${esc(projectWorkspace(project).branch)}">${icon('branch')}<code>${esc(projectWorkspace(project).branch)}</code></span>`;
const workspace=()=>workspaces.find(x=>x.id===(selectedWorkspaces.get(state.projectId)||p().workspace));
const sprintTasks=s=>p().tasks.filter(t=>t.sprintId===s.id);
const sprintState=s=>s.completion==='merged'?'done':sprintTasks(s).some(t=>['active','blocked'].includes(t.state))?'active':sprintTasks(s).some(t=>t.state==='review')?'review':'planned';
const taskState=t=>({done:'Done',active:'In progress',review:'In review',queue:'Up next',blocked:requests.some(r=>r.taskId===t.id&&r.status==='open')?'Needs answer':'Blocked'}[t.state]);
const mobile=matchMedia('(max-width:700px)');
function remember(){if(state.view==='terminal'&&$('#terminal-command'))terminalSession().draft=$('#terminal-command').value;if(isChat()){drafts.set(conversationKey(),$('#message-input').value);const scroller=conversationScroller();if(scroller.clientHeight>0)chatPositions.set(conversationKey(),scroller.scrollHeight-scroller.scrollTop-scroller.clientHeight<=4?'end':scroller.scrollTop);}positions.set(viewKey(),$('#view-body').scrollTop);if(state.view==='chat'&&state.teamId&&!state.agentId)teamTabs.set(state.projectId+'/'+state.teamId,state.tab)}
function go(patch,workspaceId=null){if(compactLead.matches&&patch.view&&patch.view!=='board')leadPanelOpen=false;const fromMenu=$('#sidebar').classList.contains('open');remember();if(workspaceId)selectedWorkspaces.set(patch.projectId||state.projectId,workspaceId);state={...state,...patch};render();closeMenu(false);if(fromMenu)$('#view-title').focus({preventScroll:true})}
function openRepository(id){const project=projects.find(x=>x.repoId===id);expandedRepos.add(id);go({repoId:id,projectId:project.id,view:'repository',teamId:null,agentId:project.lead.id,tab:'chat',sprintId:null,taskId:null})}
function openProject(id){openBoard(id)}
function openProjectChat(id){const project=projects.find(x=>x.id===id);openAgent(project.lead.id,id);$('#message-input').focus()}
function openTeam(id,pid=state.projectId,tab=null){const project=projects.find(x=>x.id===pid);expandedRepos.add(project.repoId);expandedProjects.add(pid);expandedTeams.add(pid+'/'+id);go({repoId:project.repoId,projectId:pid,view:'chat',teamId:id,agentId:null,tab:tab||teamTabs.get(pid+'/'+id)||'chat',sprintId:null,taskId:null})}
function openAgent(id,pid=state.projectId){const project=projects.find(x=>x.id===pid),t=project.teams.find(x=>x.agents.some(a=>a.id===id));expandedRepos.add(project.repoId);expandedProjects.add(pid);if(t)expandedTeams.add(pid+'/'+t.id);go({repoId:project.repoId,projectId:pid,view:'chat',teamId:t?.id||null,agentId:id,tab:'chat',sprintId:null,taskId:null})}
function openBoard(pid=state.projectId){const project=projects.find(x=>x.id===pid);expandedRepos.add(project.repoId);expandedProjects.add(pid);go({repoId:project.repoId,projectId:pid,view:'board',teamId:null,agentId:project.lead.id,tab:'chat',sprintId:null,taskId:null})}
function openSprint(id){go({view:'sprint',sprintId:id,taskId:null})}
function openTask(id){const t=p().tasks.find(x=>x.id===id);if(t)go({view:'task',taskId:id,sprintId:t.sprintId})}
function openRequest(id){const r=requests.find(x=>x.id===id);if(!r)return;openAgent(r.agentId,r.projectId);const el=$('#request-'+id);el?.scrollIntoView({block:'center'});el?.focus({preventScroll:true})}
function closeMenu(returnFocus=true){const wasOpen=$('#sidebar').classList.contains('open');$('#sidebar').classList.remove('open');$('#mobile-scrim').classList.remove('open');$('#close-sidebar').hidden=true;$('#main').inert=false;$('#sidebar').removeAttribute('role');$('#sidebar').removeAttribute('aria-modal');$('#menu').setAttribute('aria-expanded','false');if(wasOpen&&returnFocus)$('#menu').focus()}
function openMenu(){$('#context-menu').hidePopover();$('#sidebar').classList.add('open');$('#mobile-scrim').classList.add('open');$('#close-sidebar').hidden=false;$('#main').inert=true;$('#sidebar').setAttribute('role','dialog');$('#sidebar').setAttribute('aria-modal','true');$('#menu').setAttribute('aria-expanded','true');$('#close-sidebar').focus()}
mobile.addEventListener('change',e=>{if(!e.matches)closeMenu(false);resizeComposer()});
// Operational examples mirror existing page capabilities; they never contact a service.
const firstRunLoggedIn=()=>{try{return sessionStorage.getItem('sheprd-session')==='owner'}catch{return false}};
let sampleSession=api.setup.needed()&&!firstRunLoggedIn()?'login':'owner',sampleConnection='Live',authNotice='',failPermissionOnce=false,failLargeOnce=false,alertLimit=2,settingsNotice='';
const largeItems=new Map(),largeTexts=new Map();
const runtimeFor=id=>{if(!runtimeStates.has(id))runtimeStates.set(id,{state:'running',failure:null,reloadable:true});return runtimeStates.get(id)};
const agentProject=id=>projects.find(project=>agents(project).some(a=>a.id===id));
const harnessKey=a=>a.tool==='Claude Code'?'claude':(a.tool||'codex').toLowerCase();
function failureLabel(id){const run=runtimeFor(id),project=agentProject(id),a=findAgent(id,project),tool=a.tool||'The harness',m=machineFor(project).name;return ({'not-signed-in':`Not signed in to ${tool} on ${m}`,'private-login-not-signed-in':`Not signed in to this account’s private login on ${m}. Extra accounts do not use the default ${tool} login`,'model-refused':`${tool} rejected this model on ${m}`,'effort-refused':`${tool} rejected this effort on ${m}`,'mode-refused':`${tool} rejected this permission mode on ${m}`,'could-not-start':`${tool} could not start on ${m}`,'timed-out':`${tool} did not start in time on ${m}`})[run.failure]||`${tool} could not start on ${m}`}
const harnessModels=H.harness.models,harnessEfforts=H.harness.efforts;
const subscriptionFor=(a,project)=>subscriptionItems.find(s=>s.harness===harnessKey(a)&&s.machineId===machineFor(project).id&&s.enabled);
const agentSignedIn=id=>{const project=agentProject(id);return subscriptionFor(findAgent(id,project),project)?.status==='Available'};
function failureRemedy(a,project){const run=runtimeFor(a.id),m=machineFor(project).name,can=canOperate()?'':'disabled';if(run.failure?.includes('signed-in')){const signedIn=agentSignedIn(a.id);return `<p>${signedIn?`Signed in on ${esc(m)}. Resume ${esc(a.name)} to try again.`:`Sign in to ${esc(a.tool)} on ${esc(m)}, then resume ${esc(a.name)}.`}</p><div class="decision-actions">${signedIn?'':`<button class="primary" data-sign-in-agent="${a.id}" ${can}>Sign in on ${esc(m)}</button>`}<button class="${signedIn?'primary':'secondary'}" data-resume-agent="${a.id}" ${can}>Resume</button></div>`}if(['model-refused','effort-refused'].includes(run.failure)){const key=harnessKey(a),choice=run.failure==='model-refused';return `<p>Choose another ${choice?'model':'effort'}, then try again.</p><div class="failure-choice"><label>Model<select id="retry-model-${a.id}">${(harnessModels[key]||['default']).map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label>Effort<select id="retry-effort-${a.id}">${harnessEfforts.map(x=>`<option ${x==='medium'?'selected':''}>${x}</option>`).join('')}</select></label><button class="primary" data-resume-agent="${a.id}" ${can}>Try again</button></div>`}return `<p>Try ${esc(a.name)} again on ${esc(m)}. If it fails again, open a terminal there to check the harness.</p><div class="decision-actions"><button class="primary" data-resume-agent="${a.id}" ${can}>Try again</button></div>`}
function resumeAgent(id){const run=runtimeFor(id);if(run.state!=='stopped')return;if(run.failure?.includes('signed-in')&&!agentSignedIn(id)){toast('Resume failed: '+failureLabel(id));return}api.agents.resume(id,{model:$('#retry-model-'+id)?.value,effort:$('#retry-effort-'+id)?.value})}
const stopImpact=id=>{const project=agentProject(id),asks=permissionItems.filter(r=>r.agentId===id&&r.status==='open').length,task=project.tasks.find(t=>t.owner===id&&['active','review'].includes(t.state));return {asks,task,busy:pending.has(conversationKey())}};
function stopAgent(id){const run=runtimeFor(id);if(run.state==='stopped')return;api.agents.stop(id);pending.delete(conversationKey())}
const pushLabels=[['approval','Approval requests'],['question','Questions'],['failure','Agent failures'],['account','Account attention'],['other','Other alerts'],['client.web-down','Web server down'],['board.post','Board replies'],['board.no-answer','Unanswered posts'],['roles.stall','Stalled agents'],['roles.replace','Worker replacements'],['roles.runaway','Work over its expected length'],['roles.rule-first-use','First permission-rule use']];
const operationalAttention=(project=p())=>permissionItems.filter(r=>r.projectId===project.id&&r.status==='open'&&r.holder!=='lead');
const canOperate=()=>sampleSession==='owner'&&sampleConnection==='Live';
const canPrompt=()=>canOperate()&&(!state.agentId||runtimeFor(state.agentId).state==='running'&&!runtimeFor(state.agentId).failure);
const dataText=value=>esc(String(value).replace(/[\p{Cc}\p{Cf}]/gu,c=>/[\n\r\t]/.test(c)?c:'\\u{'+c.codePointAt(0).toString(16)+'}'));
function permissionView(r){return `<section class="permission-region" id="permission-${r.id}" tabindex="-1" aria-label="Approval request"><div class="decision-label"><span class="dot ${r.status==='open'?'wait':''}"></span>Approval</div><h2>${esc(r.title)}</h2><p class="op-caption">Request: ${r.id} · Tool: ${r.kind} · Call: ${r.callId}</p>${r.input?`<p class="op-caption">Action input</p><pre class="op-data">${dataText(JSON.stringify(r.input,null,2))}</pre>`:''}${r.redacted?`<p class="op-warning" role="note">${r.input?'Part of this input is hidden, so you are not seeing all of it.':`${esc(findAgent(r.agentId,projects.find(p=>p.id===r.projectId)).name)} wants to run the ${esc(r.kind)} tool. Sheprd cannot show its input.`}</p>`:''}${r.status==='open'&&r.holder==='lead'?'<p>This request is held elsewhere.</p>':r.status==='open'?`<div class="decision-actions"><button class="${r.redacted?'secondary':'primary'}" data-permission-id="${r.id}" data-permission-answer="allow" ${canOperate()&&r.answerState!=='unconfirmed'?'':'disabled'}>${!r.redacted?'Allow once':r.input?'Allow with hidden input':'Allow without seeing input'}</button><button class="secondary" data-permission-id="${r.id}" data-permission-answer="deny" ${canOperate()&&r.answerState!=='unconfirmed'?'':'disabled'}>Deny</button></div>`:r.status==='cancelled'?`<p class="op-cancelled">Cancelled because ${esc(findAgent(r.agentId,projects.find(p=>p.id===r.projectId)).name)} stopped. No answer was sent.</p>`:`<p class="op-result">${r.answer} · Answer recorded for ${esc(findAgent(r.agentId,projects.find(p=>p.id===r.projectId)).name)}. This request is closed.</p>`}${r.answerState==='unconfirmed'?'<p class="op-warning" role="alert">Could not confirm the answer. Reopen the thread to check the request before trying again.</p>':''}</section>`}
function deliveryView(d){return `<details class="thread-detail" data-delivery="${d.id}"><summary>${icon('chevron')}<span>Delivery history · ${esc(d.id)}</span><small>${esc(d.history.at(-1).split(':')[0])}</small></summary><div class="detail-content"><p>From: ${esc(d.from)} · Source: ${esc(d.source)}</p><pre class="op-data">${dataText(d.text)}</pre><ol class="delivery-events">${d.history.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></div></details>`}
function threadOperations(){if(!state.agentId)return '';const a=recipient(),run=runtimeFor(a.id),permissions=permissionItems.filter(r=>r.agentId===a.id);
 let html=run.failure?`<section class="start-failure" aria-label="Failed start"><h2>Failed to start: ${esc(failureLabel(a.id))}</h2>${failureRemedy(a,p())}</section>`:'';
 if(a.id===p().lead.id)html+=operationalAttention().map(r=>`<button class="request-link" data-open-permission="${r.id}">${icon('message')}<span>${esc(findAgent(r.agentId,projects.find(p=>p.id===r.projectId)).name)} needs approval: ${esc(r.title)}</span>${icon('arrow')}</button>`).join('');
 for(const permission of permissions.filter(r=>r.input)){const status=permission.status==='cancelled'?'Cancelled · tool not run':permission.status==='open'?'Waiting for approval':permission.answer==='Denied'?'Denied · tool not run':'Allowed · awaiting tool result';html+=`<details class="thread-detail" data-tool-call="${esc(permission.callId)}"><summary>${icon('chevron')}<span>Tool call · ${esc(permission.title)}</span><small>${status}</small></summary><div class="detail-content"><p>Call: ${esc(permission.callId)} · ${esc(permission.kind)} · ${status}</p><p class="op-caption">Input</p><pre class="op-data">${dataText(JSON.stringify(permission.input,null,2))}</pre><p class="op-caption">Output</p><p>${permission.status==='open'?'No output. The action is waiting for your approval.':permission.answer==='Denied'?'The action was denied. No tool ran.':'No result received yet. Approval does not imply success.'}</p></div></details>`}
 const largeItem=H.large[a.id];if(largeItem){const large=largeItems.get(a.id)||'unloaded';html+=`<section class="large-item" id="large-item-${a.id}" aria-label="Large thread item"><h3>Large thread item</h3><p class="op-caption">${largeItem.bytes.toLocaleString('en-US')} bytes · ${esc(largeItem.label)} · Item ${largeItem.item}</p>${large==='loaded'?`<pre class="op-data large-output">${esc(largeTexts.get(a.id))}</pre>`:`${large==='failed'?'<p class="op-warning" role="alert">Could not load this item. Try again.</p>':''}<button class="inline-link" data-load-large="${a.id}" ${canOperate()?'':'disabled'}>Load full item ${icon('arrow')}</button>`}</section>`}
 html+=deliveryItems.filter(d=>d.agentId===a.id).map(deliveryView).join('');html+=permissions.map(permissionView).join('');return html;
}
function agentControls(){if(!state.agentId)return '';const run=runtimeFor(state.agentId),stopped=run.state==='stopped';return `<div class="agent-control-row"><span><span class="dot ${run.failure?'error':stopped?'stopped':''}"></span> ${run.failure?'Failed to start':stopped?'Stopped':'Running'}</span><button class="secondary agent-command" data-agent-command="${stopped?'resume':'stop'}" ${canOperate()?'':'disabled'}>${stopped?'Resume agent':'Stop agent'}</button></div>${stopped&&!run.reloadable?'<p class="op-caption fresh-warning">This session cannot be reloaded. Resume starts a new session and loses its previous context.</p>':''}`}
function openPermission(id){const r=permissionItems.find(x=>x.id===id);if(!r)return;r.answerState=undefined;openAgent(r.agentId,r.projectId);const el=$('#permission-'+id);el?.scrollIntoView({block:'center'});el?.focus({preventScroll:true})}
function operationalAlerts(){return alerts.map(a=>({title:a.title,kind:a.kind,status:a.status,agentId:a.agentId,subject:a.subject,detail:'Delivery: '+(a.delivery?`${a.delivery.status} · Attempt ${a.delivery.attempt}${a.delivery.reason?' · Reason: '+a.delivery.reason:''}`:'Not sent'),...(a.subjectKind==='permission'?{permission:a.subject}:a.subjectKind==='question'?{request:a.subject}:{})}))}
function alertsView(){const rows=operationalAlerts();return `<div class="section-heading"><p class="muted">Notifications sent to your phone about requests and failures, and whether they arrived.</p><button class="secondary" id="refresh-alerts">Refresh alerts</button></div><div class="compact-table-wrap"><table class="alert-list compact-table" aria-label="Alerts"><thead><tr><th>Alert</th><th>Kind</th><th>Delivery</th><th>Subject</th><th>State</th><th><span class="sr-only">Open</span></th></tr></thead><tbody>${rows.slice(0,alertLimit).map(a=>`<tr><td class="machine-name"><span class="dot ${a.status==='open'?'wait':'idle'}"></span> ${a.title}</td><td>${a.kind}</td><td class="${/Failed/.test(a.detail)?'delivery-failed':''}">${esc(a.detail.replace('Delivery: ',''))}</td><td><code>${a.subject}</code></td><td>${a.status==='open'?'Open':'Cleared'}</td><td><button class="inline-link" data-alert-agent="${a.agentId}" ${a.permission?`data-alert-permission="${a.permission}"`:a.request?`data-alert-request="${a.request}"`:''}>Open ${esc(agents(projects.find(p=>agents(p).some(x=>x.id===a.agentId))).find(x=>x.id===a.agentId).name)}’s thread ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>${alertLimit<rows.length?'<button class="secondary" id="load-more-alerts">Load more alerts</button>':''}`}
function settingsView(){const s=sampleSettings,w=s.web;return `<div class="section-heading"><p class="muted">Notification delivery and access to this service.</p><button class="secondary" id="refresh-settings">Refresh settings</button></div><p id="settings-message" class="settings-message" role="status">${esc(settingsNotice)}</p><section class="settings-section"><h2>Alert push settings</h2><div class="push-settings">${pushLabels.map(([k,label])=>`<label><input type="checkbox" data-push-kind="${k}" ${s.push[k]?'checked':''}>${label}</label>`).join('')}</div></section><section class="settings-section"><h2>Alert carrier</h2><form id="carrier-form"><label for="carrier-server">Server</label><input id="carrier-server" type="url" required value="${esc(s.carrier?.server||'')}" placeholder="https://push.example"><label for="carrier-topic">Topic</label><input id="carrier-topic" required pattern="[-_A-Za-z0-9]{1,64}" maxlength="64" value="${esc(s.carrier?.topic||'')}"><div class="form-actions"><button class="secondary" id="save-carrier">Save carrier</button><button class="inline-link" type="button" id="clear-carrier">Clear carrier</button></div></form><h3>Carrier token</h3><p id="token-state">${s.tokenSet?'Token set':'No token set'} · ${esc(s.carrier?.server||'No carrier configured')}</p><form id="token-form"><label for="carrier-token">New token</label><input id="carrier-token" type="password" autocomplete="off" required ${s.carrier?'':'disabled'}><div class="form-actions"><button class="secondary" id="save-token" ${s.carrier?'':'disabled'}>Set token</button><button class="inline-link" id="clear-token" type="button" ${s.tokenSet?'':'disabled'}>Clear token</button></div></form><p class="op-caption">Write-only. The saved value is never displayed.</p></section><section class="settings-section"><h2>Web server</h2><p class="op-caption">Server state (last read): running · Configured port: ${w.port}</p><p>Saving closes web connections. Turning off the server or changing its public address may require the terminal to restore access. A port change applies at the next service start.</p><form id="web-form"><label class="check-label"><input type="checkbox" id="web-enabled" ${w.enabled?'checked':''}>Enable web server</label><div class="form-grid"><div><label for="web-port">Port</label><input id="web-port" type="number" min="1" max="65535" required value="${w.port}"></div><div><label for="web-heartbeat">Heartbeat seconds</label><input id="web-heartbeat" type="number" min="1" step="1" required value="${w.heartbeat}"></div></div><label class="check-label"><input type="checkbox" id="web-proxy" ${w.proxy?'checked':''}>Use proxy mode</label><label for="web-public">Public address (HTTPS)</label><input id="web-public" type="url" value="${esc(w.publicAddress)}" placeholder="https://sheprd.example"><p class="op-caption">Use a canonical HTTPS origin through your proxy. For an SSH tunnel, use http://127.0.0.1 at the service port and leave this empty.</p><button class="secondary" id="save-web">Save web settings</button></form></section>`}
function renderAuth(){const owner=sampleSession==='owner';$('#setup').hidden=true;$('.app').hidden=!owner;$('#auth-gate').hidden=owner;$('#auth-message').textContent=authNotice;$('#auth-message').hidden=!authNotice;$('#login-password').value='';const unavailable=sampleSession==='unavailable';$('#auth-title').textContent=unavailable?'Connection unavailable':api.setup.needed()?'Log in':'Back to your projects';$('#login-form').hidden=unavailable;$('#session-retry').hidden=!unavailable;if(!owner)$(unavailable?'#session-retry':'#login-password').focus()}
function endSampleSession(message){remember();for(const token of pending.values())api.client.stopReply(token.target,'session ended');pending.clear();document.querySelectorAll('input[type=password],#machine-code,#master-code').forEach(el=>el.value='');leadPanelOpen=!compactLead.matches;authNotice=message;sampleSession='login';closeMenu(false);for(const d of document.querySelectorAll('dialog[open]'))d.close();$('#context-menu').hidePopover();$('#sidebar').inert=false;$('.topbar').inert=false;$('#conversation-main').inert=false;renderAuth()}
function renderOperations(){renderAuth();$('#connection-status').innerHTML=`<span class="dot ${sampleConnection==='Live'?'':'wait'}"></span><span>${sampleConnection}</span>`;$('#connection-banner').hidden=sampleConnection==='Live';$('#connection-banner').innerHTML=`<span>${sampleConnection==='Connecting'?'Connecting to Sheprd…':'Reconnecting. Showing the last received state.'}</span><button class="inline-link" id="retry-connection">Try reconnecting ${icon('arrow')}</button>`;
 document.querySelectorAll('[data-system-page]').forEach(b=>b.toggleAttribute('aria-current',state.view===b.dataset.systemPage));const failedAlerts=operationalAlerts().filter(a=>a.status==='open'&&/Failed/.test(a.detail)).length;$('#alerts-count').textContent=failedAlerts?failedAlerts+' failed':'';$('#alerts-count').classList.toggle('delivery-failed',failedAlerts>0);
 $('#agent-controls').hidden=state.view!=='chat'||!state.agentId||state.tab!=='chat';$('#agent-controls').innerHTML=agentControls();$('#lead-agent-controls').innerHTML=leadBeside()?agentControls():'';
 document.querySelectorAll('[data-resolve-request],[data-discuss-request],#task-submit,#project-submit,[id=add-task]').forEach(b=>b.disabled=!canOperate());
 document.querySelectorAll('[data-account-enabled],[data-project-machine],#change-role,#connect-machine,[id=add-subscription],[data-confirm-machine],[data-connect-subscription],#finish-sample-signin,#pair-machine,#save-subscription,#join-master').forEach(el=>el.disabled=!canOperate());
 if(state.view==='settings'){document.querySelectorAll('#view-body input,#view-body button').forEach(el=>{if(!canOperate())el.disabled=true});bindSettings()}
}
function bindSettings(){
 $('#carrier-form').onsubmit=e=>{e.preventDefault();if(!canOperate())return;try{const url=new URL($('#carrier-server').value);if(!['https:','http:'].includes(url.protocol)||url.username||url.password)throw Error();const server=url.origin,topic=$('#carrier-topic').value;if(sampleSettings.tokenSet&&(sampleSettings.carrier?.server!==server||sampleSettings.carrier?.topic!==topic))api.settings.clearToken();$('#carrier-token').value='';api.settings.saveCarrier({server,topic});settingsNotice='Carrier saved.';render()}catch{settingsNotice='Enter a valid carrier server URL without credentials.';$('#settings-message').textContent=settingsNotice}};
 $('#token-form').onsubmit=e=>{e.preventDefault();const field=$('#carrier-token'),hasValue=!!field.value.trim();field.value='';if(!canOperate()||!sampleSettings.carrier||!hasValue)return;api.settings.setToken();settingsNotice='Token saved.';render()};
 $('#web-form').onsubmit=e=>{e.preventDefault();if(!canOperate())return;const address=$('#web-public').value.trim(),proxy=$('#web-proxy').checked;try{if(address){const url=new URL(address);if(url.protocol!=='https:'||url.origin!==address||url.username||url.password)throw Error()}if(proxy&&!address)throw Error()}catch{settingsNotice='Public address must be a canonical HTTPS origin, with no credentials, path, query, fragment, or default port.';$('#settings-message').textContent=settingsNotice;return}api.settings.saveWeb({enabled:$('#web-enabled').checked,port:Number($('#web-port').value),heartbeat:Number($('#web-heartbeat').value),proxy,publicAddress:address});settingsNotice='Web settings saved. A port change applies at the next service start.';render()};
}
document.addEventListener('change',e=>{if(e.target.matches('[data-push-kind]')&&canOperate()){api.settings.setPush(e.target.dataset.pushKind,e.target.checked);settingsNotice='Alert push setting saved.';$('#settings-message').textContent=settingsNotice}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;
 if(d.systemPage){go({view:d.systemPage,teamId:null,agentId:p().lead.id,tab:'chat',sprintId:null,taskId:null});return}
 if(b.id==='session-retry'){sampleSession='login';authNotice='Connection restored. Log in to continue.';renderAuth();return}
 if(b.id==='logout'){endSampleSession('You logged out.');return}
 if(b.id==='retry-connection'){remember();sampleConnection='Live';render();return}
 if(d.openPermission){openPermission(d.openPermission);return}
 if(d.permissionAnswer&&canOperate()){const r=permissionItems.find(r=>r.id===d.permissionId);if(!r||r.status!=='open'||r.holder==='lead'||r.answerState==='unconfirmed')return;remember();if(failPermissionOnce){failPermissionOnce=false;r.answerState='unconfirmed';render();return}api.permissions.answer(r.id,d.permissionAnswer);render();$('#permission-'+r.id)?.focus({preventScroll:true});return}
 if(d.agentCommand&&canOperate()){const run=runtimeFor(state.agentId);remember();if(d.agentCommand==='stop'&&run.state!=='stopped'){const impact=stopImpact(state.agentId);if(impact.asks||impact.task||impact.busy){const name=recipient().name;$('#stop-title').textContent=impact.asks?`Stop ${name} and cancel ${impact.asks} approval ${impact.asks===1?'request':'requests'}?`:`Stop ${name}?`;$('#stop-impact').textContent=[impact.asks?`${impact.asks===1?'This request is':'These requests are'} cancelled, and no answer is sent.`:'',impact.task?`Work on ${impact.task.id} stops until you resume ${name}.`:'',impact.busy?'The current reply stops.':''].filter(Boolean).join(' ');$('#stop-dialog').showModal();return}stopAgent(state.agentId)}else if(d.agentCommand==='resume')resumeAgent(state.agentId);render();return}
 if(b.id==='confirm-stop-agent'){$('#stop-dialog').close();stopAgent(state.agentId);render();return}
 if(d.resumeAgent){resumeAgent(d.resumeAgent);render();return}
 if(d.signInAgent){const project=agentProject(d.signInAgent),a=findAgent(d.signInAgent,project);let sub=subscriptionFor(a,project);if(sub){openSignIn(sub);return}const m=machineFor(project),id=harnessKey(a)+'-'+m.id;api.accounts.add({id,harness:harnessKey(a),name:m.name,machineId:m.id});openSignIn(subscriptionItems.find(s=>s.id===id));return}
 if(d.loadLarge&&canOperate()){const id=d.loadLarge;if(failLargeOnce){failLargeOnce=false;remember();largeItems.set(id,'failed');render();return}api.client.largeItem(id).then(text=>{largeTexts.set(id,text);largeItems.set(id,'loaded');remember();render()});return}
 if(d.alertAgent){if(d.alertPermission)openPermission(d.alertPermission);else if(d.alertRequest)openRequest(d.alertRequest);else{const project=projects.find(p=>agents(p).some(a=>a.id===d.alertAgent));openAgent(d.alertAgent,project.id)}return}
 if(b.id==='load-more-alerts'){alertLimit+=2;render();return}if(b.id==='refresh-alerts'){alertLimit=2;render();toast('Alerts refreshed');return}
 if(b.id==='refresh-settings'){settingsNotice='Settings refreshed.';render();return}
 if(b.id==='clear-carrier'&&canOperate()){api.settings.clearCarrier();settingsNotice='Carrier cleared.';render();return}
 if(b.id==='clear-token'&&canOperate()){api.settings.clearToken();settingsNotice='Token cleared.';render();return}
 if(d.preview){$('#notes').close();if(d.preview==='expire')endSampleSession('Your session ended. Log in again.');else if(d.preview==='login')endSampleSession('');else if(d.preview==='login-rejected')endSampleSession('The password was not accepted.');else if(d.preview==='session-unavailable'){endSampleSession('Could not check your session.');sampleSession='unavailable';renderAuth()}else if(d.preview==='reconnect'||d.preview==='connecting'){remember();sampleConnection=d.preview==='connecting'?'Connecting':'Reconnecting';render()}else if(d.preview==='live'){sampleConnection='Live';render()}else if(d.preview==='permission-failure'){failPermissionOnce=true;toast('The next permission answer will be unconfirmed.')}else if(d.preview==='held-permission'){const r=permissionItems.find(r=>r.agentId===state.agentId&&r.status==='open')||permissionItems.find(r=>r.status==='open');if(r){r.holder='lead';render()}}else if(d.preview==='failed-start'){const id=agentProject('ash')?'ash':p().lead.id;api.debug.emit('AgentStartFailed',{agentId:id,reason:$('#preview-start-reason').value});openAgent(id,agentProject(id).id)}else if(d.preview==='large-failure'){failLargeOnce=true;toast('The next large-item load will fail.')}else if(d.preview==='fresh-resume'){const run=runtimeFor(state.agentId);run.state='stopped';run.failure=null;run.reloadable=false;render()}return}
});

// Workspace and fleet design previews. There is no shell, pairing transport, or credential exchange here.
let machineMode='master',pairedMaster='',placementNotice='',diffMode='unified';
const machineFor=project=>{const selected=!project&&['terminal','source-control'].includes(state.view)?workspace()?.machineId:null;return machineItems.find(m=>m.id===(selected||projectMachines.get((project||p()).id)||thisMachine.id))};
const terminalSessions=new Map(),sourceStates=new Map();
const sourceState=()=>{const id=workspace().id;if(!sourceStates.has(id))sourceStates.set(id,{file:null,commit:null,collapsed:new Set(),historyOpen:false});return sourceStates.get(id)};
let terminalKey=()=>`${state.projectId}/${machineFor().id}/${workspace().id}`;
const terminalSession=()=>{const key=terminalKey();if(!terminalSessions.has(key))terminalSessions.set(key,{rows:[],history:[],cursor:0,draft:''});return terminalSessions.get(key)};
const harnessLabels=H.harness.labels;
let signingSubscription=null;
const allSystemPages=['home','alerts','settings','machines','subscriptions'];
function terminalView(){const session=terminalSession(),w=workspace(),m=machineFor(),g=terminalGroup(),shell=workspacePreferences.get(p().id)?.shell,live=canOperate()&&m.status==='Online',host=esc(m.name.toLowerCase());
 const bar=`<div class="terminal-top"><nav class="terminal-session-tabs" aria-label="Terminal sessions">${g.items.map(id=>`<button data-terminal-session="${id}" aria-pressed="${g.active===id}">${esc(!shell||shell==='default'?'Shell':shell)} ${id}</button>`).join('')}<button id="new-terminal" aria-label="New terminal">+</button></nav><span class="terminal-context" title="${esc(w.path)}">${icon('branch')}<code>${esc(w.branch)}</code><span>${esc(m.name)} · ${esc(m.role)}</span></span><span class="terminal-size" id="terminal-size" title="Columns and rows"></span><button class="inline-link" data-clear-terminal>Clear</button></div>`;
 const input=`<input id="terminal-command" spellcheck="false" autocapitalize="off" autocomplete="off" aria-label="Terminal command" value="${esc(session.draft)}" ${live?'':'disabled'}>`;
 if(session.alt)return `<section class="terminal-view" aria-label="Terminal">${bar}<div class="terminal-screen is-alt" id="terminal-screen"><div class="terminal-alt"><pre class="terminal-alt-body">${diffRows(session.alt).filter(([kind])=>!['removed','hunk'].includes(kind)).map(([,text],i)=>`<span class="terminal-gutter">${String(i+1).padStart(4)}</span> ${esc(text)}`).join('\n')}${'\n~'.repeat(120)}</pre><p class="terminal-alt-status"><span>NORMAL</span><span>${esc(session.alt)}</span><span>1,1</span></p></div><form id="terminal-form" class="terminal-command"><label class="sr-only" for="terminal-command">Program input</label>${input}</form></div></section>`;
 return `<section class="terminal-view" aria-label="Terminal">${bar}<div class="terminal-screen" id="terminal-screen"><div class="terminal-output" id="terminal-output" role="log" aria-live="polite">${session.rows.map(r=>`<div class="terminal-entry"><p class="terminal-prompt"><span class="terminal-host">${host}</span> <span class="terminal-path">${esc(r.path||w.path)}</span> $ ${esc(r.command)}</p><pre>${esc(r.output)}</pre></div>`).join('')}</div>${live?'':`<p class="terminal-paused">${m.status==='Online'?'Reconnecting. Input is paused.':esc(m.name)+' is offline. This session returns when it does.'}</p>`}<form id="terminal-form" class="terminal-command"><label class="terminal-prompt" for="terminal-command"><span class="terminal-host">${host}</span> <span class="terminal-path">${esc(w.path)}</span> $</label>${input}</form></div></section>`}
const terminalReply=(command,w)=>api.terminal.run(w.id,command);
function sizeTerminal(){const screen=$('#terminal-screen'),label=$('#terminal-size');if(!screen||!label)return;const style=getComputedStyle(screen),probe=document.createElement('canvas').getContext('2d');probe.font=`${style.fontSize} ${style.fontFamily}`;const cell=probe.measureText('M').width||8,line=parseFloat(style.lineHeight)||19;label.textContent=`${Math.max(1,Math.floor((screen.clientWidth-32)/cell))}×${Math.max(1,Math.floor((screen.clientHeight-24)/line))}`}
window.addEventListener('resize',sizeTerminal);
function bindTerminal(){if(state.view!=='terminal')return;const input=$('#terminal-command');input.oninput=()=>terminalSession().draft=input.value;sizeTerminal();$('#terminal-screen').onclick=e=>{if(!String(getSelection())&&!e.target.closest('input'))input.focus()};
 input.onkeydown=e=>{const s=terminalSession();if(s.alt)return;if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();s.cursor=Math.max(0,Math.min(s.history.length,s.cursor+(e.key==='ArrowUp'?-1:1)));input.value=s.history[s.cursor]||'';s.draft=input.value}else if(e.key==='c'&&e.ctrlKey){e.preventDefault();s.rows.push({command:input.value+' ^C',output:'^C'});s.draft='';render();$('#terminal-command').focus()}else if(e.key==='l'&&e.ctrlKey){e.preventDefault();s.rows=[];render();$('#terminal-command').focus()}};
 $('#terminal-form').onsubmit=e=>{e.preventDefault();if(!canOperate()||machineFor().status!=='Online')return;const command=input.value.trim(),s=terminalSession(),w=workspace();s.draft='';if(s.alt){if(/^:?(q!?|wq|x)$/.test(command))s.alt=null;render();$('#terminal-command').focus();return}if(!command){s.rows.push({command:'',output:''});render();$('#terminal-screen').scrollTop=$('#terminal-screen').scrollHeight;$('#terminal-command').focus();return}s.history.push(command);s.cursor=s.history.length;const opened=command.match(/^(?:vim|vi|nvim|less)\s+(\S+)$/);if(command==='clear')s.rows=[];else if(opened)s.alt=opened[1];else s.rows.push({command,output:terminalReply(command,w)});render();$('#terminal-screen').scrollTop=$('#terminal-screen').scrollHeight;$('#terminal-command').focus()};
}
const parseDiff=text=>text.split('\n').map(line=>line.startsWith('@@')?['hunk',line]:[line[0]==='+'?'added':line[0]==='-'?'removed':'context',line.slice(1)]);
const diffRows=path=>parseDiff((H.diffs[path]||(path?.endsWith('.md')?H.diffs['docs/README.md']:H.diffs.default)).replace('{repository}',repo().name));
function numberDiff(rows){let before=1,after=1;return rows.map(([kind,text])=>{if(kind==='hunk'){const m=text.match(/-(\d+),\d+ \+(\d+)/);before=+m[1];after=+m[2];return {kind,text}}const row={kind,text,before:kind==='added'?'':before,after:kind==='removed'?'':after};if(kind!=='added')before++;if(kind!=='removed')after++;return row})}
function pairDiffRows(rows){const pairs=[];let removed=[],added=[];const flush=()=>{for(let i=0;i<Math.max(removed.length,added.length);i++)pairs.push({left:removed[i]||null,right:added[i]||null});removed=[];added=[]};for(const r of rows){if(r.kind==='removed')removed.push(r);else if(r.kind==='added')added.push(r);else{flush();pairs.push(r.kind==='hunk'?{hunk:r}:{left:r,right:r})}}flush();return pairs}
const splitCell=(r,key)=>r?`<pre class="diff-line ${r.kind}"><span>${r[key]}</span>${esc(r.text)}</pre>`:'<pre class="diff-line filler" aria-hidden="true"> </pre>';
// As Visual Studio Code does, a split diff needs 900 pixels; below that it reads as unified.
const gitPaneWidth=()=>$('#view-body').clientWidth-280,splitFits=()=>gitPaneWidth()>=900,worktreesFit=()=>gitPaneWidth()-216>=900;
function diffBody(path,mode=diffMode){const rows=numberDiff(diffRows(path));if(mode==='split'&&splitFits())return `<div class="split-diff"><h3>Before</h3><h3>After</h3>${pairDiffRows(rows).map(x=>x.hunk?`<pre class="diff-line hunk">${esc(x.hunk.text)}</pre>`:splitCell(x.left,'before')+splitCell(x.right,'after')).join('')}</div>`;return `<div class="unified-diff">${rows.map(r=>r.kind==='hunk'?`<pre class="diff-line hunk">${esc(r.text)}</pre>`:`<pre class="diff-line ${r.kind}"><span>${r.before}</span><span>${r.after}</span><b>${r.kind==='added'?'+':r.kind==='removed'?'−':' '}</b>${esc(r.text)}</pre>`).join('')}</div>`}
const diffCounts=path=>{const rows=diffRows(path);return `<span class="added">+${rows.filter(r=>r[0]==='added').length}</span> <span class="removed-count">−${rows.filter(r=>r[0]==='removed').length}</span>`};
let diffScope='file';
const sourceCommits=()=>api.git.log(workspace().id);
function sourceControlView(){const w=workspace(),s=sourceState(),commit=sourceCommits().find(c=>c.id===s.commit),files=commit?commit.files:w.files,path=files.includes(s.file)?s.file:files[0],folders=Object.groupBy(files,f=>f.includes('/')?f.slice(0,f.lastIndexOf('/')):'.');

 return `<section class="diff-view source-control" aria-label="Git"><nav class="changed-files source-files" aria-label="Changed files"><button class="source-section" data-source-working aria-pressed="${!commit}">${icon('branch')}<strong>Changes</strong><small>${w.files.length}</small></button>${commit?`<p class="op-caption source-selection">Commit ${esc(commit.id)}</p>`:''}${Object.entries(folders).map(([dir,paths])=>`<button class="folder-row" data-source-folder="${esc(dir)}" aria-expanded="${!s.collapsed.has(dir)}">${chevron(!s.collapsed.has(dir))}${icon('folder')}${esc(dir)}</button>${s.collapsed.has(dir)?'':paths.map(f=>`<button class="source-file" data-source-file="${esc(f)}" ${f===path?'aria-current="true"':''}><span>${esc(f.split('/').at(-1))}</span><small class="file-status">M</small></button>`).join('')}`).join('')}${!files.length?'<p class="op-caption source-selection">No uncommitted changes</p>':''}<button class="source-section source-history-toggle" data-source-history aria-expanded="${s.historyOpen}">${chevron(s.historyOpen)}<strong>History</strong></button>${s.historyOpen?`<ol id="source-history" class="source-history">${sourceCommits().map(c=>`<li><button data-source-commit="${c.id}" ${c.id===s.commit?'aria-current="true"':''}><span class="commit-point"></span><span><strong>${esc(c.title)}</strong><small>${esc(c.ref)} · ${c.id}</small></span></button></li>`).join('')}</ol>`:''}</nav><div class="diff-content">${path?`<header class="diff-toolbar"><code id="diff-path">${diffScope==='all'&&files.length>1?files.length+' files':esc(path)}</code><div class="diff-toolbar-controls"><div class="segmented" aria-label="Files shown"><button data-diff-scope="file" aria-pressed="${diffScope!=='all'}">This file</button><button data-diff-scope="all" aria-pressed="${diffScope==='all'}">All files</button></div><div class="segmented" aria-label="Diff layout"><button data-diff-mode="unified" aria-pressed="${diffMode==='unified'}">Unified</button><button data-diff-mode="split" aria-pressed="${diffMode==='split'}">Split</button></div></div></header>${diffMode==='split'&&!splitFits()?'<p class="op-caption" id="split-note">Split needs a wider window, so this diff is unified.</p>':diffMode==='split'&&!worktreesFit()?'<p class="op-caption" id="split-note">Split hides the worktree list. Choose Unified to bring it back.</p>':''}<p id="diff-context" class="op-caption">${commit?'Commit '+esc(commit.id):'Uncommitted changes'} · ${esc(w.branch)} · ${esc(machineFor().name)}</p>${diffScope==='all'?files.map(f=>`<section class="diff-file"><header class="diff-file-header"><code>${esc(f)}</code><small>${diffCounts(f)}</small></header>${diffBody(f)}</section>`).join(''):diffBody(path)}`:`<div class="empty"><h2>No uncommitted changes</h2><p>Nothing is waiting on ${esc(w.branch)}. Open History to inspect a commit.</p></div>`}</div></section>`}
function workspaceSettingsView(){const w=projectWorkspace(),prefs=workspacePreferences.get(p().id)||{shell:'default'};return `<form id="workspace-settings-form"><section class="settings-section"><h2>Where this project runs</h2><p>Where ${esc(p().name)} and its agents work.</p><dl id="workspace-location" class="workspace-location"><dt>Repository</dt><dd>${esc(repo().name)}</dd><dt>Branch</dt><dd><code>${esc(w.branch)}</code></dd><dt>Checkout</dt><dd>${w.path===repositoryLocations.get(w.repoId+'/'+w.machineId)?'Main checkout':'Project worktree'}</dd><dt>Folder</dt><dd><code>${esc(w.path)}</code></dd><dt>Machine</dt><dd>${esc(machineFor().name)}</dd></dl><p class="op-caption">This is the project’s assigned worktree. The Viewing picker only changes the branch you inspect.</p></section><section class="settings-section"><h2>Terminal</h2><label for="workspace-shell">Preferred shell</label><select id="workspace-shell">${[['default','Machine default'],['bash','Bash'],['zsh','Zsh']].map(([v,label])=>`<option value="${v}" ${prefs.shell===v?'selected':''}>${label}</option>`).join('')}</select><p class="op-caption">Used for new terminal sessions in this worktree.</p><div class="form-actions"><button class="primary" id="save-workspace-settings">Save project settings</button><p id="workspace-settings-status" role="status" class="settings-message"></p></div></section></form>`}
function machinesView(){return `<section class="machine-page"><div class="section-heading"><p>Computers connected to this Sheprd.</p>${machineMode==='master'?'<button class="secondary" id="connect-machine">Connect machine</button>':''}</div><div class="fleet-settings"><p class="machine-role"><span>This computer</span><strong id="machine-role">${machineMode==='master'?'Master':'Worker'}</strong><button class="secondary" id="change-role">Change role</button></p><p class="op-caption" id="machine-mode-state">${machineMode==='master'?esc(thisMachine.name)+' coordinates this Sheprd.':pairedMaster?'Paired to '+esc(pairedMaster):'Pair with a master to receive projects.'}</p></div>${machineMode==='worker'?`<form class="settings-section" id="join-master-form"><h2>Join a master</h2><label for="master-address">Master address</label><input id="master-address" type="url" placeholder="https://studio.example" required><label for="master-code">Pairing code</label><input id="master-code" autocomplete="off" placeholder="Enter pairing code" required><button class="secondary" id="join-master">Pair with master</button></form>`:`<div class="compact-table-wrap"><table class="compact-table machine-table" aria-label="Machines"><thead><tr><th>Machine</th><th>Status</th><th>Role</th><th>Agent slots</th><th>Projects</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${machineItems.map(m=>`<tr><td class="machine-name">${esc(m.name)}</td><td><span class="dot ${m.status==='Online'?'':m.status==='Offline'?'idle':'wait'}"></span> ${esc(m.status)}</td><td>${esc(m.role)}</td><td>${projects.filter(p=>machineFor(p).id===m.id).flatMap(agents).length} of ${m.slots}</td><td>${projects.filter(p=>machineFor(p).id===m.id).length}</td><td>${m.status==='Awaiting confirmation'?`<button class="inline-link" data-confirm-machine="${m.id}">Confirm pairing</button>`:m.status==='Online'?`<button class="inline-link" data-new-on-machine="${m.id}">New project here</button>`:''}</td></tr>`).join('')}</tbody></table></div><section class="fleet-placement"><h2>Project placement</h2><p id="placement-message" role="status">${esc(placementNotice||'Choose a machine when starting a project. Placement changes below apply to future runs.')}</p><div class="compact-table-wrap"><table class="compact-table placement-table"><thead><tr><th>Project</th><th>Repository</th><th>Branch</th><th>Next run on</th></tr></thead><tbody>${projects.map(project=>`<tr><td>${esc(project.name)}</td><td>${esc(repoFor(project).name)}</td><td><code>${esc(projectWorkspace(project).branch)}</code></td><td><select data-project-machine="${project.id}" aria-label="Machine for ${esc(project.name)}">${machineItems.map(m=>`<option value="${m.id}" ${(futureProjectMachines.get(project.id)||machineFor(project).id)===m.id?'selected':''} ${m.status==='Online'&&repositoryLocations.has(project.repoId+'/'+m.id)?'':'disabled'}>${esc(m.name)}${m.status==='Online'?'':' · '+m.status}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div></section>`}</section>`}
function openSignIn(sub){const machine=machineItems.find(m=>m.id===sub.machineId),online=machine.status==='Online';signingSubscription=sub.id;$('#subscription-login-title').textContent=`Sign in to ${harnessLabels[sub.harness]} on ${machine.name}`;$('#subscription-login-context').textContent=`Subscription ${sub.name}. This login stays private to this subscription.`;$('#sign-in-close').textContent='Cancel';if(!online){$('#sign-in-output').textContent='';$('#sign-in-status').textContent=`${machine.name} is ${machine.status.toLowerCase()}, so its terminal cannot open.`;$('#subscription-login').showModal();return}$('#sign-in-output').textContent='';$('#sign-in-status').textContent='Waiting for sign-in.';$('#subscription-login').showModal();api.accounts.signIn(sub.id).then(login=>{$('#sign-in-output').textContent=`$ ${login.command}\nOpen ${login.url}\nand enter the code ${login.code}`})}
$('#subscription-login').addEventListener('close',()=>{if(signingSubscription)api.accounts.cancelSignIn(signingSubscription)});
function subscriptionsView(){return `<div class="section-heading"><p>Separate accounts for each harness, on each machine. Each one signs in privately.</p><button class="secondary" id="add-subscription">Add subscription</button></div><div class="compact-table-wrap"><table class="compact-table subscription-table" aria-label="Subscriptions"><thead><tr><th>Name</th><th>Harness</th><th>Machine</th><th>Active agents</th><th>Sign-in</th><th>Use for new work</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${subscriptionItems.map(a=>`<tr data-account-harness="${a.harness}" data-account-name="${esc(a.name)}"><td class="machine-name">${esc(a.name)}</td><td>${harnessLabels[a.harness]}</td><td>${esc(machineItems.find(m=>m.id===a.machineId)?.name||thisMachine.name)}</td><td>${a.active} ${a.active===1?'agent':'agents'}</td><td><span class="dot ${a.status==='Available'?'':'wait'}"></span> ${a.status}</td><td><label class="account-enable"><input type="checkbox" data-account-enabled="${a.id}" ${a.enabled?'checked':''}><span class="sr-only">Use ${esc(a.name)} for new work</span></label></td><td>${a.status!=='Available'?`<button class="inline-link" data-connect-subscription="${a.id}">Connect subscription ${icon('arrow')}</button>`:''}</td></tr>`).join('')}</tbody></table></div>`}
function renderWorkspaceTabs(){const visible=!['repositories','repository',...allSystemPages].includes(state.view),active=['sprint','task'].includes(state.view)?'board':state.view;$('#workspace-tabs').hidden=!visible;$('#workspace-tabs').innerHTML=[['board','Board'],['chat','Chat'],['terminal','Terminal'],['source-control','Git'],['workspace-settings','Settings']].map(([id,label])=>`<button role="tab" id="${id==='board'?'tab-board':id==='chat'?'tab-project-chat':'workspace-tab-'+id}" data-main-view="${id}" aria-selected="${active===id}" tabindex="${active===id?0:-1}" aria-controls="view-body">${label}</button>`).join('')}
function bindWorkspaceTools(){bindTerminal();if(state.view==='workspace-settings'){$('#workspace-settings-form').onsubmit=e=>{e.preventDefault();if(!canOperate())return;api.project.savePreferences(p().id,{shell:$('#workspace-shell').value});$('#workspace-settings-status').textContent='Project settings saved.'};document.querySelectorAll('#workspace-settings-form input,#workspace-settings-form select,#workspace-settings-form button').forEach(el=>el.disabled=!canOperate())}if(state.view==='machines'){
 $('#join-master-form')?.addEventListener('submit',e=>{e.preventDefault();if(!canOperate())return;try{const url=new URL($('#master-address').value);if(url.protocol!=='https:'||url.origin!==$('#master-address').value||url.username||url.password)throw Error();pairedMaster=url.origin;api.machines.join(url.origin);render()}catch{toast('Use a canonical HTTPS master address.')}});
 document.querySelectorAll('[data-project-machine]').forEach(el=>el.onchange=e=>{if(machineMode!=='master'||!canOperate())return;const target=machineItems.find(m=>m.id===e.target.value),project=projects.find(p=>p.id===el.dataset.projectMachine);if(target?.status!=='Online'||!repositoryLocations.has(project.repoId+'/'+target.id))return;api.machines.place(el.dataset.projectMachine,target.id);placementNotice=projects.find(p=>p.id===el.dataset.projectMachine).name+' assigned to '+target.name+' for future runs.';render()})}
}
document.addEventListener('change',e=>{if(e.target.matches('[data-account-enabled]')&&canOperate()){api.accounts.setEnabled(e.target.dataset.accountEnabled,e.target.checked)}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;
 if(d.mainView){remember();if(d.mainView==='board')openBoard();else if(d.mainView==='mocks')openMocks();else go({view:d.mainView,tab:'chat',sprintId:null,taskId:null});return}
 if(d.clearTerminal!==undefined){terminalSession().rows=[];render();return}
 if(d.diffMode){diffMode=d.diffMode;render();return}
 if(d.diffScope){diffScope=d.diffScope;render();return}
 if(d.sourceFile){sourceState().file=d.sourceFile;diffScope='file';render();if(mobile.matches)$(".diff-content")?.scrollIntoView({block:'start'});return}
 if(d.sourceFolder){const s=sourceState();s.collapsed.has(d.sourceFolder)?s.collapsed.delete(d.sourceFolder):s.collapsed.add(d.sourceFolder);render();return}
 if(d.sourceHistory!==undefined){sourceState().historyOpen=!sourceState().historyOpen;render();return}
 if(d.sourceCommit){sourceState().commit=d.sourceCommit;render();return}
 if(d.sourceWorking!==undefined){sourceState().commit=null;render();return}
 if(b.id==='connect-machine'){$('#machine-form').reset();$('#pair-start').hidden=false;$('#pair-code').hidden=true;$('#machine-dialog').showModal();return}
 if(d.copy){if(!navigator.clipboard){getSelection().selectAllChildren($('#'+d.copy));toast('Selected. Copy it from here, because this address cannot use the clipboard.');return}navigator.clipboard.writeText($('#'+d.copy).textContent).then(()=>toast('Copied'),()=>toast('Could not copy. Select the text instead.'));return}
 if(b.id==='change-role'){const toWorker=machineMode==='master',workers=machineItems.filter(m=>m.role==='Worker').length,count=projects.length;$('#role-title').textContent=toWorker?'Make this computer a worker?':'Make this computer the master?';$('#role-impact').textContent=toWorker?`${workers} ${workers===1?'worker':'workers'} and ${count} ${count===1?'project':'projects'} depend on ${thisMachine.name}. They receive no new work until a master takes over, and this computer must pair with a master.`:pairedMaster?`This computer stops taking work from ${pairedMaster}, and it starts coordinating its own projects.`:'This computer starts coordinating projects, and other computers can pair with it.';$('#confirm-role').textContent=toWorker?'Make worker':'Make master';$('#role-dialog').showModal();return}
 if(b.id==='confirm-role'){machineMode=machineMode==='master'?'worker':'master';api.machines.setRole(thisMachine.id,machineMode==='master'?'Master':'Worker');$('#role-dialog').close();render();return}
 if(d.confirmMachine&&canOperate()){const m=machineItems.find(m=>m.id===d.confirmMachine);if(m&&machineMode==='master')api.machines.confirm(m.id);render();return}
 if(b.id==='add-subscription'){$('#subscription-form').reset();$('#subscription-machine').innerHTML=machineItems.filter(m=>m.status==='Online').map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('');$('#subscription-error').hidden=true;$('#subscription-dialog').showModal();return}
 if(d.connectSubscription){openSignIn(subscriptionItems.find(a=>a.id===d.connectSubscription));return}
});

const attentionNumber=n=>n?`<span class="attention-number" role="img" aria-label="${n} ${n===1?'needs':'need'} attention">${n}</span>`:'';
function renderSidebar(){
 $('#repo-tree').innerHTML=repositories.map(r=>`<section class="repo-group" data-repo="${r.id}"><div class="repo-heading"><button class="disclosure" data-repo-toggle="${r.id}" aria-label="${expandedRepos.has(r.id)?'Collapse':'Expand'} ${esc(r.name)}" aria-expanded="${expandedRepos.has(r.id)}" aria-controls="repo-${r.id}">${chevron(expandedRepos.has(r.id))}</button>${icon('folder')}<button class="repo-label" data-open-repo="${r.id}" ${state.view==='repository'&&state.repoId===r.id?'aria-current="page"':''}>${esc(r.name)}</button>${attentionNumber(allAttention().filter(x=>x.project.repoId===r.id).length)}<button class="icon-button" data-add-project="${r.id}" aria-label="Add project to ${esc(r.name)}">${icon('plus')}</button></div><div class="repo-children" id="repo-${r.id}" ${expandedRepos.has(r.id)?'':'hidden'}>${projects.filter(x=>x.repoId===r.id).map(project=>{
 const active=project.id===state.projectId&&state.view!=='home'&&!['repositories','repository','alerts','settings','machines','subscriptions'].includes(state.view),expanded=expandedProjects.has(project.id),rs=[...projectRequests(project),...operationalAttention(project)];
 return `<section class="project-group" data-project-id="${project.id}"><div class="project-heading ${active?'active':''}"><button class="disclosure" data-project-toggle="${project.id}" aria-label="${expanded?'Collapse':'Expand'} ${esc(project.name)} teams" aria-expanded="${expanded}" aria-controls="project-${project.id}">${chevron(expanded)}</button><button class="project-select" data-project="${project.id}" ${active?'aria-current="page"':''}><span><span class="project-label">${esc(project.name)}</span><span class="project-lead"><span>${esc(project.lead.name)}</span><span aria-hidden="true">·</span>${projectBranch(project)}</span></span>${attentionNumber(allAttention().filter(x=>x.project.id===project.id).length)}</button></div><div class="project-children" id="project-${project.id}" ${expanded?'':'hidden'}>${project.teams.map(t=>{
 const open=expandedTeams.has(project.id+'/'+t.id),chosen=active&&state.teamId===t.id&&state.view==='chat';
 return `<div class="team-heading"><button class="disclosure" data-team-toggle="${t.id}" data-project-ref="${project.id}" aria-label="${open?'Collapse':'Expand'} ${esc(t.name)} agents" aria-expanded="${open}" aria-controls="team-${project.id}-${t.id}">${chevron(open)}</button><button class="team-select" data-team="${t.id}" data-project-ref="${project.id}" ${chosen&&!state.agentId?'aria-current="page"':''}><span title="${t.agents.length} ${t.agents.length===1?'agent':'agents'}">${esc(t.name)}</span>${attentionNumber(allAttention().filter(x=>x.project.id===project.id&&t.agents.some(a=>a.id===x.agent.id)).length)}</button></div><div class="team-agents" id="team-${project.id}-${t.id}" ${open?'':'hidden'}>${t.agents.map(a=>{const needs=rs.some(x=>x.agentId===a.id),run=runtimeFor(a.id),failed=Boolean(run.failure),stopped=run.state==='stopped',task=project.tasks.find(x=>x.owner===a.id&&['active','review'].includes(x.state)),status=failed?'Failed to start':operationalAttention(project).some(r=>r.agentId===a.id)?'Needs approval':needs?(stopped?'Stopped · Needs answer':'Needs answer'):stopped?'Stopped':task?.state==='review'?'Reviewing':task?'Working':'Ready';return `<button class="agent-link ${failed?'failed':needs?'needs-attention':''}" data-agent="${a.id}" data-project-ref="${project.id}" ${chosen&&state.agentId===a.id?'aria-current="page"':''} title="${esc(status+(task?' · '+task.id+' '+task.title:''))}"><span class="dot ${failed?'error':needs?'wait':stopped?'stopped':task?'':'idle'}"></span><span class="agent-name">${esc(a.name)}</span><small>${status}</small></button>`}).join('')}</div>`
 }).join('')}</div></section>`
 }).join('')}</div></section>`).join('');
}
function turn(a,content,time='10:38',options={}){return `<article class="turn ${options.user?'user-turn':''} ${options.sample?'sample-response':''}"><div class="turn-head">${options.user?'':`<span class="avatar" aria-hidden="true">${esc(a.initial)}</span>`}<strong>${options.user?'You':esc(a.name)}</strong>${!options.user&&a.tool?`<span class="tool-name">${esc(a.tool)}</span>`:''}<time>${time}</time></div><div class="turn-content">${content}</div></article>`}
const taskLink=(id,label)=>`<button class="inline-link" data-task="${id}">${esc(label||id)} ${icon('arrow')}</button>`;
const requestLink=r=>`<button class="request-link" data-open-request="${r.id}">${icon('message')}<span>${esc(r.summary)}</span>${icon('arrow')}</button>`;
const boardLink=()=>`<button class="inline-link" data-board="${p().id}">Open sprint board ${icon('arrow')}</button>`;
let runs=(label,lines)=>`<details class="run-details"><summary>${icon('chevron','chevron')}<span>${label}</span></summary><div class="run-lines">${lines.map(x=>`<span>${icon('check')}${x}</span>`).join('')}</div></details>`;
function decision(r,project=projects.find(p=>p.id===r.projectId)){return `<section class="decision" id="request-${r.id}" tabindex="-1" aria-label="${esc(r.title)}"><div class="decision-label"><span class="dot ${r.status==='open'?'wait':''}"></span>${r.status==='open'?'Question · '+(project.sprints.find(s=>s.id===r.sprintId)?.label||r.taskId||project.name):'Question answered'}</div><h2>${esc(r.title)}</h2><p>${esc(r.question)}</p>${r.recommendation?`<p>${esc(r.recommendation)}</p>`:''}${r.status==='open'&&r.holder==='lead'?'<p>This request is held elsewhere.</p>':r.status==='open'?`<div class="decision-actions">${r.answer?`<button class="primary" data-resolve-request="${r.id}">${esc(r.answer)}</button>`:''}<button class="inline-link" data-discuss-request="${r.id}">Discuss another approach</button></div>`:`<p class="decision-result">${icon('check')} ${esc(r.answer||'Answered')}. Your direction is recorded with this sprint.</p>`}</section>`}
const timeOf=entry=>entry.occurred>H.clock?'Just now':new Date(entry.occurred).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:H.timeZone});
const linkPattern=/\[([^\]]+)\]\((task|board|mocks):([^)]*)\)/;
function richText(text){const known=new Set(p().tasks.map(t=>t.id));return text.split(/(\[[^\]]+\]\((?:task|board|mocks):[^)]*\))/).map(piece=>{const m=piece.match(linkPattern);if(m)return m[2]==='task'?taskLink(m[3],m[1]):m[2]==='mocks'?(state.view==='mocks'||!p().mocks?'':`<button class="inline-link" data-open-mocks="${p().id}">${esc(m[1])} ${icon('arrow')}</button>`):state.view==='board'?'':boardLink();return esc(piece).replace(/\b[A-Z]{2,4}-\d+\b/g,id=>known.has(id)?taskLink(id):id)}).join('')}
const textBlocks=text=>text.split(/\n{2,}/).map(block=>new RegExp('^'+linkPattern.source+'$').test(block.trim())?richText(block.trim()):`<p>${richText(block).replace(/\n/g,'<br>')}</p>`).join('');
function partsHtml(parts){let html='',files=0;const flush=()=>{if(files)html+=`<button class="inline-link" data-show-changes="${assignedWorkspace().id}">Review ${plural(files,'changed file')} ${icon('arrow')}</button>`;files=0};for(const part of parts){if(part.type==='file'){files++;continue}flush();if(part.type==='text')html+=textBlocks(part.text);else if(part.type==='tool')html+=runs(part.title,part.lines);else if(part.type==='question'){const r=requests.find(x=>x.id===part.id);if(r)html+=decision(r)}}flush();return html}
function entryHtml(entry,extra=''){if(entry.type==='stopped')return '<div class="reply-state">Response stopped · Your message stays in the conversation</div>';if(entry.type==='prompt'){const from=entry.sender?._tag==='agent'?agentProject(entry.sender.agentId)&&findAgent(entry.sender.agentId,agentProject(entry.sender.agentId)):null,body=entry.text.split('\n').map(esc).join('<br>')+'';return turn(from||{name:'You'},`<p>${body}</p>${entry.context?.length?`<div class="sent-context">${esc(entry.context.join(' · '))}</div>`:''}`,timeOf(entry),{user:!from})}const project=agentProject(entry.agentId),a=project&&findAgent(entry.agentId,project);return turn(a||{name:entry.agentId,initial:'?'},partsHtml(entry.parts)+extra,timeOf(entry),{sample:entry.reply})}
function entriesHtml(entries,links=''){const anchor=entries.findLastIndex(e=>e.type==='turn'&&!e.reply);return entries.map((entry,i)=>entryHtml(entry,i===anchor?links:'')).join('')+(anchor<0?links:'')}
function chatDay(entries){const day=value=>new Date(value).toLocaleDateString('en-GB',{timeZone:H.timeZone,day:'numeric',month:'short'}),last=entries.findLast(e=>e.occurred)?.occurred;return !last||last>H.clock||day(last)===day(H.clock)?'Today':day(last)}
const teamChannel=(t=team(),project=p())=>[...channels.values()].find(c=>c.group===project.id+'/'+t.id);
function conversationEntries(){if(state.agentId){const a=recipient(),entries=threads.get(a.id)||[];return runtimeFor(a.id).failure?entries.filter(e=>!e.occurred||e.occurred>H.clock):entries}return teamChannel()?.posts||[]}
function agentConversation(){const a=recipient();return entriesHtml(conversationEntries(),a.id===p().lead.id?projectRequests().filter(r=>r.agentId!==a.id).map(requestLink).join(''):'')}
const teamConversation=()=>entriesHtml(conversationEntries(),projectRequests().filter(r=>r.teamId===team().id).map(requestLink).join(''));
function chatView(){return `<div class="chat-date">${chatDay(conversationEntries())} · ${state.agentId?esc(recipient().role):'Shared team chat'}</div>${state.agentId?agentConversation():teamConversation()}${threadOperations()}${pending.has(conversationKey())?'<div class="reply-state" role="status"><span class="dot"></span>Working…</div>':''}`}
function taskTable(tasks){return `<table class="task-list" aria-label="Plan tasks"><tbody>${tasks.map(t=>`<tr><td><span class="task-state ${t.state}" aria-hidden="true"></span></td><td>${t.id}</td><td><button class="task-name" data-task="${t.id}">${esc(t.title)}</button><span class="task-subtitle">${taskState(t)}</span></td><td><button class="inline-link" data-talk-agent="${t.owner}">${esc(findAgent(t.owner).name)}</button></td></tr>`).join('')}</tbody></table>`}
function tasksView(){const tasks=p().tasks.filter(t=>t.teamId===state.teamId);return `<div class="section-heading"><h2>${tasks.filter(t=>t.state==='done').length} of ${tasks.length} tasks complete</h2><button class="inline-link" id="add-task">${icon('plus')} Add task</button></div>${taskTable(tasks)}`}
function changesView(){return sourceControlView()}
function boardView(){if(!p().sprints.length&&p().mocks&&!p().mocks.approvedAt)return `<div class="empty"><h2>No sprints yet</h2><p>${esc(designTeam()?.name||'The Design team')} is drawing the screens. The plan starts when you approve the mocks.</p><div class="empty-actions"><button class="primary" data-open-mocks="${p().id}">Open the mocks</button><button data-focus-lead>Talk to ${esc(p().lead.name)}</button></div></div>`;if(!p().sprints.length)return `<div class="empty"><h2>No sprints yet</h2><p>Talk to ${esc(p().lead.name)} about the outcome. Your project's plan and sprints will appear here.</p><button class="primary" data-focus-lead>Talk to ${esc(p().lead.name)}</button></div>`;
 const columns=[['planned','Planned'],['active','In progress'],['review','Review'],['done','Done']];
 return `<div class="board-intro"><span>The project plan, from the next sprint to verified work.</span><button class="inline-link" data-focus-lead>Talk to ${esc(p().lead.name)} ${icon('arrow')}</button></div><div class="kanban">${columns.map(([id,label])=>{const values=p().sprints.filter(s=>sprintState(s)===id);return `<section class="kanban-column" aria-label="${label}"><h2 class="column-heading ${id}"><span class="dot"></span>${label}<small>${values.length}</small></h2>${values.map(s=>{const tasks=sprintTasks(s),done=tasks.filter(t=>t.state==='done').length,rs=projectRequests().filter(r=>r.sprintId===s.id),dependency=s.needs.map(n=>p().sprints.find(x=>x.id===n)).find(n=>n.completion!=='merged');return `<button class="sprint-card" data-sprint="${s.id}"><span class="sprint-id">${s.label} · ${s.phase}</span><h3>${esc(s.name)}</h3><p>${esc(s.goal)}</p><span class="sprint-meta"><span>${esc([...new Set([s.owner,...tasks.map(t=>t.owner)])].map(id=>findAgent(id).name).join(', '))}</span><span>${done}/${tasks.length} tasks</span></span><span class="sprint-progress" aria-hidden="true"><span style="--progress:${tasks.length?done/tasks.length*100:0}%"></span></span>${rs.length?'<span class="sprint-note"><span class="dot wait"></span>Needs answer</span>':dependency?`<span class="sprint-dependency">Waiting on ${dependency.label}</span>`:s.completion==='merged'?'<span class="sprint-dependency">Verified · Merged to main</span>':''}</button>`}).join('')}${values.length?'':'<p class="muted" style="font-size:12px;padding:10px 0">No sprints here</p>'}</section>`}).join('')}</div>`;
}
function sprintView(){const s=p().sprints.find(x=>x.id===state.sprintId),tasks=sprintTasks(s),rs=projectRequests().filter(r=>r.sprintId===s.id);return `<button class="inline-link back-link" data-board="${p().id}">← Project board</button><div class="sprint-detail"><div><p class="detail-summary">${esc(s.goal)}</p><section class="detail-section"><div class="section-heading"><h2>Plan tasks</h2>${s.completion==='merged'?'':`<button class="inline-link" id="add-task">${icon('plus')} Add task</button>`}</div>${taskTable(tasks)}</section>${rs.length?`<section class="detail-section"><h2>Needs answer</h2>${rs.map(requestLink).join('')}</section>`:''}<section class="detail-section"><h2>Completion evidence</h2><p class="muted" style="font-size:13px">${s.completion==='merged'?esc(s.evidence)+' · Release status is tracked separately.':'This sprint is not complete. Review, verification, and merge evidence will be recorded here.'}</p></section></div><aside class="detail-sidebar" aria-label="Sprint context"><dl><div><dt>Owner</dt><dd><button class="inline-link" data-talk-agent="${s.owner}">${esc(findAgent(s.owner).name)}</button></dd></div><div><dt>Phase</dt><dd>${s.phase}</dd></div><div><dt>Team</dt><dd>${[...new Set(tasks.map(t=>p().teams.find(x=>x.id===t.teamId)?.name))].map(esc).join(', ')||'Not assigned'}</dd></div><div><dt>Depends on</dt><dd>${s.needs.length?s.needs.map(id=>{const dep=p().sprints.find(x=>x.id===id);return `<button class="inline-link" data-sprint="${id}">${dep.label} · ${esc(dep.name)}</button>`}).join('<br>'):'No dependencies'}</dd></div><div><dt>Plan</dt><dd>${esc(p().name)} / ${s.label}</dd></div></dl></aside></div>`}
function taskView(){const t=p().tasks.find(x=>x.id===state.taskId),s=p().sprints.find(x=>x.id===t.sprintId),w=workspaces.find(x=>x.id===t.workspace),r=requests.find(x=>x.taskId===t.id),owner=findAgent(t.owner).name,story=taskStories[t.id]||{summary:s.goal,done:['Meets the goal of '+s.label,'Reviewed by the team lead'],activity:[{title:t.addedByOwner?'Added by you':'Assigned by '+p().lead.name,detail:owner+' owns '+t.id+'.'}]},timeline=`<ol class="task-timeline">${story.activity.map(step=>{const open=step.question&&requests.find(x=>x.id===step.question)?.status==='open',shown=step.question?(open?step.open:step.answered):step;return `<li class="${open?'waiting':''}"><strong>${esc(shown.title)}</strong><small>${esc(shown.detail)}</small></li>`}).join('')}</ol>`;return `<button class="inline-link back-link" data-sprint="${s.id}">← ${s.label} · ${esc(s.name)}</button><div class="sprint-detail"><div><p class="detail-summary">${esc(story.summary)}</p>${r?.status==='open'?requestLink(r):r?'<p class="decision-result">Owner direction recorded. This request is resolved.</p>':''}<section class="detail-section"><h2>Done when</h2><ul class="task-done">${story.done.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section class="detail-section"><h2>Activity</h2>${timeline}</section>${w.files.length?`<section class="detail-section"><h2>Changed files</h2><div class="run-files">${w.files.map(f=>`<button class="inline-link" data-inspect-file="${esc(f)}" data-inspect-workspace="${w.id}">${esc(f)} ${icon('arrow')}</button>`).join('')}</div></section>`:''}<div class="decision-actions"><button class="primary" data-talk-agent="${t.owner}">Talk to ${esc(owner)}</button><button class="inline-link" data-show-changes="${t.workspace}" data-changes-team="${t.teamId}">View changes ${icon('arrow')}</button></div></div><aside class="detail-sidebar" aria-label="Assignment context"><dl><div><dt>Task</dt><dd>${t.id}</dd></div><div><dt>Status</dt><dd>${taskState(t)}</dd></div><div><dt>Owner</dt><dd>${esc(owner)}</dd></div><div><dt>Team</dt><dd>${esc(p().teams.find(x=>x.id===t.teamId).name)}</dd></div><div><dt>Assigned branch</dt><dd><code>${esc(w.branch)}</code></dd></div><div><dt>Worktree</dt><dd><code>${esc(w.path)}</code></dd></div></dl></aside></div>`}
function repositoriesView(){return `<p class="detail-summary">Repositories connected from your workspace. Start a project inside a repository to talk through what you want to build.</p><table class="repos-table"><thead><tr><th>Repository</th><th class="hide-small">Projects</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${repositories.map(r=>`<tr><td><button class="inline-link" data-open-repo="${r.id}">${esc(r.name)}</button><span class="repo-path">${esc(r.path)}</span></td><td class="hide-small">${projects.filter(x=>x.repoId===r.id).length} projects</td><td><button class="inline-link" data-add-project="${r.id}">New project ${icon('plus')}</button></td></tr>`).join('')}</tbody></table>`}
