 if(b.id==='close-lead-panel'){setLeadPanel(false);return}
 if(d.projectChat){openProjectChat(d.projectChat);return}
 if(d.board){openBoard(d.board);return}
 if(d.team){openTeam(d.team,d.projectRef);return}
 if(d.openTeam){openTeam(d.openTeam);return}
 if(d.agent){openAgent(d.agent,d.projectRef);return}
