$('#message-form').onsubmit=e=>{
 e.preventDefault();if(!canPrompt())return;const text=$('#message-input').value.trim(),key=conversationKey();if(!text||pending.has(key))return;
 remember();const target=replyTarget();api.client.prompt(target,text,{context:(composerAttachments.get(key)||[]).map(x=>x.label),account:composerAccounts.get(key),mockScreen:state.view==='mocks'&&mocksPane().pane==='screens'?mocksPane().screenId:undefined});composerAttachments.delete(key);drafts.delete(key);pending.set(key,{target});render();conversationScroller().scrollTop=conversationScroller().scrollHeight;$('#message-input').focus();
};
